def plugin_proposal_links():
    if 'APP_PLUGIN_RUNTIME' not in globals():
        return {}
    merged = {}
    for links in APP_PLUGIN_RUNTIME.collect('proposal_links'):
        if isinstance(links, dict):
            merged.update(links)
    return merged


def runs_schedules():
    """Whether this server is the one that does things on a schedule: the run
    queue, the assistant's watch and a vault's automations. A preview shares
    the real config, so it leaves them to the server it previews, and so does
    a test, which imports this file beside the real config."""
    return SERVER_STARTED and not IS_PREVIEW


def calendar_meetings():
    """The next day's meetings with their details, or None while the Calendar
    plugin is off or has no calendar it can read."""
    found = APP_PLUGIN_RUNTIME.invoke('calendar', 'upcoming') if 'APP_PLUGIN_RUNTIME' in globals() else None
    return found if isinstance(found, list) else None


def tailscale_phone_url():
    """Orc's private phone address while the Tailscale plugin is on and its
    Phone access is running, else None."""
    found = APP_PLUGIN_RUNTIME.invoke('tailscale', 'phone_url') if 'APP_PLUGIN_RUNTIME' in globals() else None
    return found if isinstance(found, str) else None


def close_tailscale():
    """Stops the Tailscale plugin's loopback servers before this process exits."""
    if 'APP_PLUGIN_RUNTIME' in globals():
        APP_PLUGIN_RUNTIME.invoke('tailscale', 'close')


