FRAME_DENY_HEADERS = {
    "Content-Security-Policy": "frame-ancestors 'none'",
    "X-Frame-Options": "DENY",
}
FRAME_SELF_HEADERS = {
    "Content-Security-Policy": "frame-ancestors 'self'",
    "X-Frame-Options": "SAMEORIGIN",
}
# A file read from disk (a run folder, a checkout, an attachment) was written
# by an agent, a tool or a user, never by Orc. A page, SVG or XML document
# among them still runs its script, but in a sandbox's opaque origin: it cannot
# read Orc's API, storage or the page framing it, and Orc refuses its writes
# (Origin: null). Only types that cannot run script skip the sandbox. Orc's own
# page opens run-folder and checkout pages on the files origin instead
# (ui/run_file_origin.py), so this is the answer for every other load.
SANDBOXED_FILE_HEADERS = {
    "Content-Security-Policy": (
        "sandbox allow-scripts allow-forms allow-popups "
        "allow-popups-to-escape-sandbox allow-modals allow-downloads; "
        "frame-ancestors 'self'"),
    "X-Frame-Options": "SAMEORIGIN",
    "Vary": "Sec-Fetch-Dest, Sec-Fetch-Site",
}
INERT_FILE_TYPES = ("image/", "audio/", "video/", "font/", "text/plain",
                    "text/css", "text/javascript", "text/csv", "application/json",
                    "application/pdf")
FONT_EXTENSIONS = (".woff2", ".woff", ".ttf", ".otf")


def disk_file_type(full):
    """The Content-Type a file from disk is served as. The platform's table
    names some audio oddly (.m4a as audio/mp4a-latm, .flac as audio/x-flac), so
    media takes the types the media route uses."""
    if full.endswith((".md", ".mdx", ".log")):
        return "text/plain"
    return (run_files.MEDIA_TYPES.get(os.path.splitext(full)[1].lower())
            or mimetypes.guess_type(full)[0] or "text/plain")


def runs_script(full, ctype):
    """True for a file a browser runs script in when it opens it: a page, an
    SVG, an XML document. Fonts go by extension, since the platform's type
    table may not know them."""
    return (not full.lower().endswith(FONT_EXTENSIONS)
            and (ctype == "image/svg+xml" or not ctype.startswith(INERT_FILE_TYPES)))


def chat_download_type(name):
    ctype = mimetypes.guess_type(name)[0] or "application/octet-stream"
    if (name.lower().endswith((".mht", ".mhtml", ".webarchive"))
            or ctype in ("text/html", "text/xml", "text/xsl", "application/xml", "multipart/x-mixed-replace")
            or ctype.endswith("+xml")):
        return "application/octet-stream"
    return ctype


@functools.cache
def bundled_font_bytes():
    return tuple(font.read_bytes() for font in (Path(HERE) / "fonts").glob("*.woff2"))


def disk_file_headers(full, ctype, body=None):
    """A sandboxed mockup may load its copy of a bundled font from an opaque origin."""
    headers = {"X-Content-Type-Options": "nosniff"}
    if full.lower().endswith(FONT_EXTENSIONS) and body is not None and body in bundled_font_bytes():
        headers["Access-Control-Allow-Origin"] = "null"
    elif runs_script(full, ctype):
        headers.update(SANDBOXED_FILE_HEADERS)
    return headers


