def replaces_ship_page(meta):
    """True when the Pull request panel stands in for the run's Ship page."""
    return isinstance(meta, dict) and meta.get("lifecycleVersion") == 4


def minimal_shell_run(meta):
    return isinstance(meta, dict) and meta.get("route") == MINIMAL_SHELL_ROUTE


# Planning sessions (skills/_shared/planning-session.md): batched question
# rounds on one page, then a Next steps bar. Not a lifecycle run -- no Plan,
# Build, delivery authority or Ship -- so every reader keys on meta.route.
PLANNING_ROUTE = run_relationships.PLANNING_ROUTE
PLANNING_PHASE = "planning"
PLANNING_TAB = "planning/planning.html"
PLANNING_SOURCE = "planning/planning.mdx"
PLANNING_QUESTIONS = "planning-questions.json"
PLANNING_OUTCOME = "planning"


def planning_run(meta):
    return isinstance(meta, dict) and meta.get("route") == PLANNING_ROUTE


def planning_outcome(meta):
    """The closed planning record: Done wrote the terminal triple."""
    return (planning_run(meta) and meta.get("outcome") == PLANNING_OUTCOME
            and meta.get("phase") == "done" and meta.get("status") == "complete")


def planning_state(meta):
    planning = meta.get("planning") if isinstance(meta, dict) else None
    return planning if isinstance(planning, dict) else {}


def planning_complete(meta):
    return planning_run(meta) and planning_state(meta).get("state") == "complete"


# One source of truth with `bin/orc-publish-question --repair`, which must
# strip exactly the keys this predicate rejects. Defined in run_relationships
# because that is the module the repair path lives in and serve.py already
# imports it; aliased here so every existing reader keeps its own name.
QUESTION_FORBIDDEN_META = run_relationships.QUESTION_FORBIDDEN_META
QUESTION_FORBIDDEN_ARTIFACTS = run_relationships.QUESTION_FORBIDDEN_ARTIFACTS
QUESTION_FORBIDDEN_PREFIXES = run_relationships.QUESTION_FORBIDDEN_PREFIXES
ATTACHMENT_TYPES = staged_images.TYPES
VIDEO_ATTACHMENT_TYPES = staged_images.VIDEO_TYPES


def is_question_run(meta, artifact_paths=None, run_dir=None):
    """Strict prospective question outcome; malformed combinations stay ordinary."""
    if (not isinstance(meta, dict)
            or meta.get("outcome") != "question"
            or meta.get("phase") != "done"
            or meta.get("status") != "complete"
            or any(key in meta for key in QUESTION_FORBIDDEN_META)):
        return False
    if artifact_paths is None:
        if not isinstance(run_dir, str):
            return False
        try:
            if not os.path.isfile(os.path.join(run_dir, ANSWER_TAB)) \
                    or os.path.getsize(os.path.join(run_dir, ANSWER_TAB)) <= 0:
                return False
        except OSError:
            return False
        artifacts = {}
        for root, dirs, names in os.walk(run_dir):
            dirs[:] = [name for name in dirs if not name.startswith(".")]
            for name in names:
                if name.startswith("."):
                    continue
                path = os.path.relpath(os.path.join(root, name), run_dir)
                try:
                    artifacts[path] = os.path.getsize(os.path.join(root, name))
                except OSError:
                    return False
    else:
        artifacts = {}
        for item in artifact_paths:
            if isinstance(item, dict):
                artifacts[item.get("path")] = item.get("size")
            elif isinstance(item, str):
                artifacts[item] = None
        if not isinstance(artifacts.get(ANSWER_TAB), (int, float)) \
                or artifacts[ANSWER_TAB] <= 0:
            return False
    if artifacts.get("grilling.mdx") not in (None, 0):
        return False
    return not any(
        path in QUESTION_FORBIDDEN_ARTIFACTS
        or any(path.startswith(prefix) for prefix in QUESTION_FORBIDDEN_PREFIXES)
        for path in artifacts if isinstance(path, str))


def has_question_outcome(meta):
    return isinstance(meta, dict) and "outcome" in meta


def is_orchestration_worker(meta):
    return isinstance(meta, dict) and meta.get("route") == "orchestration-worker"


ORCHESTRATION_WORKER_DELIVERY_ERROR = (
    "The coordinator manages delivery for orchestration workers.")


# A published eval stays settled, but its Chat answers questions about the
# comparison, so these reach its session.
EVALS_PARENT_ACTIONS = ("chat-send", "chat-stop", "chat-send-now", "chat-retry",
                        "chat-resume-queue", "open-session", "session", "open-terminal")


def published_evals_parent(meta):
    return (isinstance(meta, dict) and meta.get("route") == "evals"
            and meta.get("outcome") == "evals")


LEGACY_READ_ONLY_ERROR = "legacy runs are read-only; start a fresh run"


def canonical_phase(phase):
    return "recap" if phase == LEGACY_RECAP_PHASE else phase


def is_recap_phase(phase):
    return canonical_phase(phase) == "recap"


def is_final_landing_phase(phase):
    """Present for current runs; Recap/ship for historical final gates."""
    return phase == PRESENT_PHASE or is_recap_phase(phase)


def final_landing_tab(meta):
    """Return the final page owned by this run's current/historical contract."""
    if not isinstance(meta, dict):
        return RECAP_TAB
    if meta.get("lifecycleVersion") in (3, 4):
        return SHIP_TAB
    if meta.get("phase") == PRESENT_PHASE \
            or PRESENT_PHASE in (meta.get("gatedPhases") or []):
        return PRESENT_TAB
    return RECAP_TAB


def at_final_landing_stop(meta, page=None):
    if (not isinstance(meta, dict) or is_orchestration_worker(meta)
            or meta.get("status") != "awaiting-gate"):
        return False
    phase = meta.get("phase")
    if meta.get("lifecycleVersion") in (3, 4):
        return (phase == SHIP_PHASE
                and (page is None or page == SHIP_TAB))
    if not is_final_landing_phase(phase):
        return False
    expected = PRESENT_TAB if phase == PRESENT_PHASE else RECAP_TAB
    return page is None or page == expected


def mvp_checkpoint_version(meta):
    if not isinstance(meta, dict) or meta.get("mode") != "gated":
        return None
    version = meta.get("mvpCheckpointVersion")
    return version if type(version) is int and version in (1, 2) else None


def at_mvp_stop(meta):
    """Whether this is the gated hands-on checkpoint, never a delivery gate."""
    return (mvp_checkpoint_version(meta) is not None
            and meta.get("phase") == MVP_PHASE
            and meta.get("status") == "awaiting-gate")


attachment_image_type = staged_images.image_type


GALLERY_GIF_MAX_FRAMES = 30
GALLERY_GIF_MAX_FRAME_BYTES = 512 * 1024
GALLERY_GIF_MAX_BODY_BYTES = 8 * 1024 * 1024
# A send-off MP4 is every 60 fps frame of a scene of up to 5.1 s, drawn at a
# 1280×800 window: 307 JPEGs, which in the busiest look (Synthwave night, PR
# opened) post as about 64 MB.
GALLERY_MP4_MAX_FRAMES = 360
GALLERY_MP4_MAX_BODY_BYTES = 128 * 1024 * 1024
GALLERY_MP4_MAX_WIDTH = 1280
GALLERY_GIF_TTL_SECONDS = 24 * 60 * 60
GALLERY_EXPORT_FORMATS = ("gif", "mp4")
_FRAME_DATA_URL = re.compile(r"^data:image/(png|jpeg);base64,([A-Za-z0-9+/=\s]+)$")


def gallery_gif_dir(create=False):
    """Ephemeral jail for encoded gallery exports (~/.orc/gallery-gifs)."""
    base = os.path.join(CONFIG_DIR, "gallery-gifs")
    if create:
        os.makedirs(base, mode=0o700, exist_ok=True)
    return os.path.realpath(base)


def zip_run_dir(zf, run_dir):
    """Add one run dir's files to an open zip, named relative to RUNS.

    Symlinks are skipped (following one would zip content from outside the
    runs tree), and so are files that vanish or cannot be read mid-walk."""
    for root, _dirs, files in os.walk(run_dir):
        for fname in files:
            full = os.path.join(root, fname)
            if os.path.islink(full) or not os.path.isfile(full):
                continue
            try:
                zf.write(full, os.path.relpath(full, RUNS))
            except OSError:
                continue


def gallery_gif_path(token, ext="gif"):
    """Resolve one export inside the jail, or None when the token would escape."""
    if (not token or token != os.path.basename(token) or token.startswith(".")
            or not re.fullmatch(r"[A-Za-z0-9_-]{8,64}", token)
            or ext not in GALLERY_EXPORT_FORMATS):
        return None
    base = gallery_gif_dir()
    full = os.path.join(base, token + "." + ext)
    return full if os.path.realpath(full) == full else None


def gallery_gif_slug(title):
    slug = re.sub(r"[^a-z0-9]+", "-", (title or "").lower()).strip("-")
    return (slug[:48] or "gallery-scene")


def purge_gallery_gifs(now=None):
    """Drop encoded exports older than the TTL; best-effort, never raises.

    Copied exports live in a token folder so they paste with their real
    name; the day-long TTL keeps one on the clipboard pasteable."""
    now = time.time() if now is None else now
    try:
        base = gallery_gif_dir()
        for name in os.listdir(base):
            full = os.path.join(base, name)
            try:
                if now - os.path.getmtime(full) <= GALLERY_GIF_TTL_SECONDS:
                    continue
                if os.path.isdir(full) and not os.path.islink(full):
                    shutil.rmtree(full, ignore_errors=True)
                elif name.endswith(tuple("." + ext for ext in GALLERY_EXPORT_FORMATS)):
                    os.unlink(full)
            except OSError:
                continue
    except OSError:
        pass


def decode_frame_data_url(value, kinds=("png",)):
    """Return raw image bytes from a PNG or JPEG data URL, or None when invalid."""
    if not isinstance(value, str) or len(value) > GALLERY_GIF_MAX_FRAME_BYTES * 2:
        return None
    match = _FRAME_DATA_URL.match(value.strip())
    if not match or match.group(1) not in kinds:
        return None
    try:
        body = base64.b64decode(match.group(2), validate=True)
    except Exception:
        return None
    if (not body or len(body) > GALLERY_GIF_MAX_FRAME_BYTES
            or attachment_image_type(body) != "image/" + match.group(1)):
        return None
    return body


def _write_frames(work, frames):
    paths = []
    for index, body in enumerate(frames):
        ext = "jpg" if attachment_image_type(body) == "image/jpeg" else "png"
        path = os.path.join(work, "frame-%03d.%s" % (index, ext))
        with open(path, "wb") as handle:
            handle.write(body)
        paths.append(path)
    return paths


def _encoder_error(result, fallback):
    detail = (result.stderr or result.stdout or b"").decode(
        "utf-8", "replace").strip().splitlines()
    return detail[-1] if detail else fallback


def encode_gallery_gif(frames, delay_cs=10, delays_cs=None):
    """Encode PNG frames into one looping GIF.

    ffmpeg builds one palette from every frame and only redraws what changed,
    which keeps a scene small enough to post; ImageMagick is the fallback.
    delays_cs, one per frame, lets a slideshow hold each slide; ffmpeg snaps
    those to 40 ms steps. Returns (gif_bytes, None) or (None, error_message).
    """
    ffmpeg = shutil.which("ffmpeg")
    magick = shutil.which("magick")
    if not (ffmpeg or magick):
        return None, "ffmpeg or ImageMagick (magick) is not installed"
    if not frames:
        return None, "no frames"
    delay = max(2, min(100, int(delay_cs or 10)))
    delays = ([max(2, min(1000, int(d))) for d in delays_cs] if delays_cs
              else [delay] * len(frames))
    if len(delays) != len(frames):
        return None, "one delay per frame"
    work = tempfile.mkdtemp(prefix="orc-gallery-gif-")
    try:
        paths = _write_frames(work, frames)
        out = os.path.join(work, "out.gif")
        palette = ("split[a][b];[a]palettegen=stats_mode=diff[p];"
                   "[b][p]paletteuse=dither=bayer:bayer_scale=4:diff_mode=rectangle")
        if ffmpeg and delays_cs:
            # The concat list drops the last entry's duration unless that
            # frame is listed once more.
            listing = os.path.join(work, "frames.txt")
            with open(listing, "w", encoding="utf-8") as handle:
                handle.write("ffconcat version 1.0\n")
                for path, frame_delay in zip(paths, delays):
                    handle.write("file '%s'\nduration %.2f\n"
                                 % (os.path.basename(path), frame_delay / 100))
                handle.write("file '%s'\n" % os.path.basename(paths[-1]))
            command = [ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                       "-f", "concat", "-i", listing, "-vf", palette,
                       "-fps_mode", "passthrough", "-loop", "0", out]
        elif ffmpeg:
            command = [ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                       "-framerate", "%.4f" % (100 / delay),
                       "-i", os.path.join(work, "frame-%03d.png"),
                       "-vf", palette, "-loop", "0", out]
        else:
            timed = [arg for path, frame_delay in zip(paths, delays)
                     for arg in ("-delay", str(frame_delay), path)]
            command = [magick, "-loop", "0", *timed, "-layers", "Optimize", out]
        try:
            result = subprocess.run(command, capture_output=True, timeout=30)
        except (OSError, subprocess.TimeoutExpired) as exc:
            return None, "gif encode failed: %s" % exc
        if result.returncode != 0 or not os.path.isfile(out):
            return None, _encoder_error(result, "gif encode failed")
        with open(out, "rb") as handle:
            gif = handle.read()
        if not gif.startswith((b"GIF87a", b"GIF89a")):
            return None, "encoder returned a non-GIF"
        return gif, None
    finally:
        shutil.rmtree(work, ignore_errors=True)


def encode_gallery_mp4(frames, fps=24):
    """Encode frames into a silent MP4.

    H.264 at a modest CRF keeps a five-second scene well under
    the upload limits of Slack and Discord. Returns (mp4_bytes, None) or
    (None, error_message).
    """
    ffmpeg = shutil.which("ffmpeg")
    if not ffmpeg:
        return None, "ffmpeg is not installed"
    if not frames:
        return None, "no frames"
    fps = max(1.0, min(60.0, float(fps or 24)))
    work = tempfile.mkdtemp(prefix="orc-gallery-mp4-")
    try:
        paths = _write_frames(work, frames)
        pattern = os.path.join(work, "frame-%03d." + paths[0].rsplit(".", 1)[1])
        out = os.path.join(work, "out.mp4")
        # yuv420p needs even dimensions, whatever size the frames arrive at.
        video = ("scale='max(2,trunc(min(%d,iw)/2)*2)':-2:flags=lanczos,format=yuv420p"
                 % GALLERY_MP4_MAX_WIDTH)
        command = [ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                   "-framerate", "%.3f" % fps, "-i", pattern, "-vf", video,
                   "-c:v", "libx264", "-preset", "slow", "-crf", "26",
                   "-profile:v", "high", "-movflags", "+faststart", out]
        try:
            result = subprocess.run(command, capture_output=True, timeout=60)
        except (OSError, subprocess.TimeoutExpired) as exc:
            return None, "mp4 encode failed: %s" % exc
        if result.returncode != 0 or not os.path.isfile(out):
            return None, _encoder_error(result, "mp4 encode failed")
        with open(out, "rb") as handle:
            mp4 = handle.read()
        if mp4[4:8] != b"ftyp":
            return None, "encoder returned a non-MP4"
        return mp4, None
    finally:
        shutil.rmtree(work, ignore_errors=True)


def unique_download_path(folder, filename):
    """Finder's naming: name.ext, then "name 2.ext", "name 3.ext", ..."""
    stem, ext = os.path.splitext(filename)
    candidate = os.path.join(folder, filename)
    number = 2
    while os.path.lexists(candidate):
        candidate = os.path.join(folder, "%s %d%s" % (stem, number, ext))
        number += 1
    return candidate


def copy_file_to_pasteboard(path):
    """Copy a file reference so the receiving application can paste the file."""
    script = ("ObjC.import('AppKit');"
              "function run(argv){const board=$.NSPasteboard.generalPasteboard;"
              "board.clearContents;"
              "return board.writeObjects($([$.NSURL.fileURLWithPath(argv[0])]));}")
    try:
        result = windows_host.copy_file(path) if windows_host.WSL else subprocess.run(["osascript", "-l", "JavaScript", "-e", script, path],
                                capture_output=True, timeout=10)
    except (OSError, subprocess.TimeoutExpired) as exc:
        return "could not copy: %s" % exc
    if result.returncode != 0 or result.stdout.strip() != b"true":
        return _encoder_error(result, "could not copy to the clipboard")
    return None

# statuses the action-menu status picker (PATCH /api/runs/<id>) may set — the
# documented meta.json status vocabulary
EDITABLE_STATUSES = {
    "running", "awaiting-gate", "escalated", "merging", "complete", "merged",
    "cancelled"}

# statuses where the session may still be blocked on an AskUserQuestion worth
# surfacing (see pending_question) — a finished run's transcript never is
LIVE_STATUSES = {
    "running", "awaiting-gate", "escalated", "merging", "merging-to-parent"}

# a run in one of these has no session left to paste into. "complete" stays
# out because a completed run still dispatches its delivery actions (Open PR,
# Merge to main) into its pane.
FINISHED_STATUSES = {"merged", "merged-to-parent", "cancelled"}

# stop-implying statuses the runs payload demotes to "running" while the run's
# owned session still shows a live spinner (see scan) — the agent writes these
# mid-turn before it actually stops. UI-driven transitions (merging/merged/
# cancelled) are excluded: the user just clicked those.
HELD_WHILE_RUNNING = {"awaiting-gate", "escalated", "complete"}

# Same rule for the gate-page render path, minus "complete": a finished run's
# published Recap/Present page must keep rendering its delivered content. The
# run card can wait to say "Done" while the pane is busy; an artifact the user
# already has must never regress into a loading screen.
RENDER_HELD_WHILE_RUNNING = HELD_WHILE_RUNNING - {"complete"}
# A side note is a nudge, not a brief. The cap keeps one paste inside a single
# prompt and stops the build page becoming a place to type a second plan.
BTW_MAX_CHARS = 2000
# Build-page notes queued until the session's turn ends. The cap bounds one
# flushed prompt at FOLLOW_UPS_MAX notes of BTW_MAX_CHARS each.
FOLLOW_UPS_FILE = "follow-ups.json"
FOLLOW_UPS_MAX = 20
FOLLOW_UP_RETRY_SECONDS = 15
FOLLOW_UP_FLUSH_STATUSES = ("running", "awaiting-gate")
CHAT_QUEUE_STATUSES = (*FOLLOW_UP_FLUSH_STATUSES, "escalated", "complete", "merging", "merging-to-parent")
# How long Send now waits for an interrupted turn to let go of the prompt.
SEND_NOW_SETTLE_SECONDS = 6
# One Chat message. Longer than a build-page note because Chat is the place
# to type a real follow-up, and still one paste into the agent's prompt.
CHAT_MAX_CHARS = 12000
def effective_run_status(meta, activity, held=HELD_WHILE_RUNNING):
    status = meta.get("status")
    if status not in held:
        return status
    # Unlike form gates, MVP is a published hands-on handoff with its own
    # server-owned advancement action. Once durable state says it is ready,
    # keep shell routing and controls on that checkpoint even if the agent's
    # final turn is still marked active in its session.
    if status == "awaiting-gate" and at_mvp_stop(meta):
        return status
    if callable(activity):
        activity = activity()
    return "running" if activity == "running" else status


