# --- QA hub ---------------------------------------------------------------
# Any run with QA steps (ui/qa_steps.py) opens the QA window. Review in Orc
# starts one code review run for a pull request: the checkout's app starts
# first, the steps are seeded from the pull request's QA section, and the
# review agent types them before it hunts for findings
# (skills/orc-review/SKILL.md). A QA run is what Review in Orc started before
# that: its own agent wrote the steps (skills/_shared/qa-run.md) and a child
# run reviewed the code. Those still open and settle as before.
def unadopted_qa_checkout(meta):
    """The checkout a run's QA app would start in when Orc has not adopted it
    yet, or None: a QA run whose first adoption failed, or a code review of a
    PR running in a review checkout that is not the project's main one."""
    worktree = meta.get("worktree") if isinstance(meta.get("worktree"), dict) else {}
    if worktree.get("adapter"):
        return None
    if is_qa_run(meta):
        return worktree.get("path") if worktree.get("enabled") else None
    checkout, project = meta.get("repoPath"), meta.get("mainRepoPath")
    if (reviewed_pull_request(meta) and isinstance(checkout, str) and isinstance(project, str)
            and os.path.isdir(checkout) and canonical_path(checkout) != canonical_path(project)):
        return checkout
    return None


def qa_brief(pr, checkout):
    """What Review in Orc records about its pull request in inputs/qa.json.
    The title and author are someone else's words, so they stay data and the
    server words the prompt."""
    return {"url": pr["url"], "repo": pr["repo"], "number": pr["number"], "title": pr["title"],
            "author": pr["author"], "baseRef": pr["baseRef"], "checkout": checkout}


def qa_review_stub_fields(brief, checkout):
    """The launch stub of the review Review in Orc starts: which pull request
    it reviews, so the QA window walks it before `orc-local-review init`
    runs, and the checkout as its worktree."""
    return {
        "source": "pull-request", "sourceRef": brief["url"],
        "review": {"prUrl": brief["url"], "prAuthor": brief["author"], "prTitle": brief["title"],
                   "baseRef": brief["baseRef"]},
        # The checkout is the Pull requests plugin's, so Orc never deletes it.
        # `orc-worktree adopt-checkout` fills in the adapter and starts the app.
        "worktree": {"enabled": True, "path": checkout, "managedByOrc": False,
                     "operation": new_worktree_operation("start")},
    }


def begin_qa_review(run_id, checkout):
    """Starts the review checkout's app beside Review in Orc's review, without
    holding up the launch: the review's agent starts without waiting."""
    threading.Thread(target=_adopt_run_checkout, args=(run_id, checkout),
                     name="orc-qa-app", daemon=True).start()


def new_worktree_operation(action, state="requested", error=None):
    operation = {"token": secrets.token_hex(12), "action": action, "state": state,
                 "updatedAt": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")}
    if error:
        operation["error"] = error
    return operation


def review_checkout(url, required=False):
    """The pull request at `url` checked out into its review worktree on
    `orc-review/pr-<n>`, as `(detail, project, checkout)`, or None when Orc
    gives that PR no checkout: the Pull requests plugin is off or the PR's
    repository is not a configured project. An existing clean checkout moves
    to the PR's latest commit. Raises ValueError with the reason when the
    checkout fails, or, when `required`, instead of returning None."""
    service = pr_manager_service()
    if service is None:
        if required:
            raise ValueError("Pull requests plugin is disabled.")
        return None
    match = REVIEWED_PR_URL.fullmatch(url) if isinstance(url, str) else None
    if not required and (not match or not service.project_for(match.group(1), read_config()[0])):
        return None
    try:
        detail = service.detail(url)
        review = detail["review"]
        if not review["available"]:
            if required:
                raise ValueError(review["reason"])
            return None
        checkout = service.prepare_review_worktree(review["project"], detail["repo"], detail["number"],
                                                   detail["baseRef"])
    except run_pull_request.PrManagerError as error:
        raise ValueError(error.message) from None
    return detail, review["project"], checkout


def review_launch_pr_url(prompt):
    """The pull request a review launched by its link names, or None."""
    match = REVIEWED_PR_URL.search(prompt or "")
    return match.group(0).rstrip("/") if match else None


def note_run_meta(run_id, fields):
    """Writes `fields` into a just-reserved run's meta."""
    with RUN_STATUS_LOCK:
        meta = run_meta(run_id)
        if not meta:
            return
        meta.update(fields)
        _write_run_meta(run_id, meta)
    invalidate_runs_body()


def note_review_checkout_failure(run_id, url, error):
    """A review whose PR checkout failed at launch runs as before; its QA
    window says why it has no app and offers Set up to try again."""
    with RUN_STATUS_LOCK:
        meta = run_meta(run_id)
        if not meta:
            return
        review = meta.get("review") if isinstance(meta.get("review"), dict) else {}
        review.setdefault("prUrl", url)
        meta["review"] = review
        meta["worktree"] = {"enabled": False, "operation": new_worktree_operation(
            "setup", "failed", "Orc could not check out this PR: %s" % error)}
        _write_run_meta(run_id, meta)
    invalidate_runs_body()


def review_needs_checkout(meta):
    """The pull request a review launched by its link reviews, when that
    review has no checkout of its own: it started before PR reviews got one,
    or its checkout failed. Set up in the QA window makes one. A review of
    your local branch keeps running on the main checkout."""
    pr = reviewed_pull_request(meta)
    wt = meta.get("worktree") if isinstance(meta.get("worktree"), dict) else {}
    project = meta.get("mainRepoPath")
    if not pr or wt.get("enabled") or meta.get("branch") or not isinstance(project, str):
        return None
    try:
        with open(os.path.join(RUNS, str(meta.get("runId")), "inputs", "start-prompt.txt")) as handle:
            prompt = handle.read(64 * 1024)
    except (OSError, ValueError):
        return None
    if review_launch_pr_url(prompt) != pr["url"].rstrip("/"):
        return None
    service = pr_manager_service()
    owner = service.project_for(pr["repo"], read_config()[0]) if service is not None else None
    return pr if owner and canonical_path(owner) == canonical_path(project) else None


def _set_up_review_checkout(run_id, token, url):
    """Set up: checks the PR out into its own worktree and starts its app."""
    try:
        found, error = review_checkout(url, required=True), None
    except ValueError as exc:
        found, error = None, str(exc)
    if error:
        _update_worktree_operation(run_id, token, "failed", "Orc could not check out this PR: %s" % error)
        invalidate_runs_body()
        return
    checkout = found[2]
    with RUN_STATUS_LOCK:
        meta = run_meta(run_id)
        worktree = meta.get("worktree") if isinstance(meta.get("worktree"), dict) else {}
        if (worktree.get("operation") or {}).get("token") != token:
            return
        # Orc did not make the PR, so the checkout is never Orc's to delete.
        worktree.update(enabled=True, path=checkout, managedByOrc=False)
        meta["worktree"] = worktree
        _write_run_meta(run_id, meta)
    _adopt_run_checkout(run_id, checkout)


def _adopt_run_checkout(run_id, checkout):
    """Makes `checkout` the run's worktree and starts its app: a QA run's
    review checkout, or a devd tree that lost its orc-devd registration. An
    earlier QA run of the same pull request used the same checkout, so its
    app stops first: one checkout, one app."""
    token = ((run_meta(run_id).get("worktree") or {}).get("operation") or {}).get("token")
    real = os.path.realpath(checkout)
    for run in scan_cached():
        worktree = (run.get("meta") or {}).get("worktree")
        if (run.get("id") != run_id and isinstance(worktree, dict) and isinstance(worktree.get("server"), dict)
                and isinstance(worktree.get("path"), str) and os.path.realpath(worktree["path"]) == real):
            with contextlib.suppress(OSError, subprocess.SubprocessError):
                subprocess.run([sys.executable, _worktree_helper_path(), "stop-server",
                                "--run-dir", os.path.join(RUNS, run["id"])], capture_output=True, timeout=60)
    if token:
        _update_worktree_operation(run_id, token, "running")
    error = None
    try:
        res = subprocess.run(
            [sys.executable, _worktree_helper_path(), "adopt-checkout",
             "--run-dir", os.path.join(RUNS, run_id), "--path", checkout],
            capture_output=True, timeout=1200)
    except (OSError, subprocess.SubprocessError) as exc:
        error = "Could not run orc-worktree: %s" % exc
    else:
        payload = _worktree_helper_json(res.stdout if res.returncode == 0 else res.stderr)
        started = payload.get("serverStart") or payload.get("devd") or {}
        if res.returncode:
            error = payload.get("error") or "The app could not be started."
        elif isinstance(started, dict) and started.get("ok") is False:
            error = started.get("error") or "The app could not be started."
    if token:
        _update_worktree_operation(run_id, token, "failed" if error else "succeeded", error)
    with WORKTREE_APP_HEALTH_LOCK:
        WORKTREE_APP_HEALTH.pop(run_id, None)
    invalidate_runs_body()


def _recreate_run_worktree(run_id, token):
    """Builds the run's worktree again from its branch (a settled run whose
    tree was cleaned up) and starts its app, through the same `orc-worktree
    setup-*` a new run uses. A tree a finished run still holds is handed
    over to this one."""
    meta = run_meta(run_id)
    adapter = "devd" if devd_launch.is_devd_repo(meta.get("mainRepoPath")) else "generic"
    _update_worktree_operation(run_id, token, "running")
    error = None
    try:
        res = subprocess.run(
            [sys.executable, _worktree_helper_path(), "setup-" + adapter,
             "--run-dir", os.path.join(RUNS, run_id)], capture_output=True, timeout=1200)
    except (OSError, subprocess.SubprocessError) as exc:
        error = "Could not run orc-worktree: %s" % exc
    else:
        payload = _worktree_helper_json(res.stdout if res.returncode == 0 else res.stderr)
        started = payload.get("serverStart") or payload.get("devd") or {}
        if res.returncode:
            error = payload.get("error") or "The worktree could not be recreated."
        elif payload.get("enabled") is False:
            error = "Worktrees are turned off for this project, so Orc did not recreate one."
        elif isinstance(started, dict) and started.get("ok") is False:
            error = started.get("error") or "The app could not be started."
    _update_worktree_operation(run_id, token, "failed" if error else "succeeded", error)
    with WORKTREE_APP_HEALTH_LOCK:
        WORKTREE_APP_HEALTH.pop(run_id, None)
    invalidate_runs_body()


def settle_qa_run(run_id, finished):
    """Finish QA closes a QA run and Reopen QA brings it back. Other runs
    keep their own lifecycle: QA is something done to them, not their state."""
    with RUN_STATUS_LOCK:
        meta = run_meta(run_id)
        if not is_qa_run(meta) or meta.get("status") == "cancelled":
            return
        meta.update(status="complete", phase="done") if finished \
            else meta.update(status="awaiting-gate", phase=QA_PHASE)
        _write_run_meta(run_id, meta)
    invalidate_runs_body()


def _local_branch_exists(repo, branch):
    try:
        found = subprocess.run(["git", "-C", repo, "rev-parse", "--verify", "--quiet",
                                "refs/heads/" + branch], capture_output=True, timeout=10)
    except (OSError, subprocess.SubprocessError):
        return False
    return found.returncode == 0


def _qa_missing_server(project):
    name = os.path.basename((project or "").rstrip("/")) or "this project"
    fix = {"text": "Set up Live dev server in the project's Runs & workspace settings."}
    if project and repo_present(project):
        key = canonical_path(project)
        for path, entry in (read_config()[0].get("repos") or {}).items():
            if isinstance(entry, dict) and canonical_path(path) == key:
                if entry.get("worktree") is not False:
                    fix["setupProject"] = path
                else:
                    fix["text"] = "Enable worktrees in the project's Runs & workspace settings first."
                break
    return {"reason": "%s has no dev server set up." % name, "fix": fix}


def _qa_app_plan(meta):
    """How the QA window can bring up the run's own app: `("start", None)`
    when the tree is on disk and Start runs it (attaching it to orc-devd
    first when it lost its registration), `("recreate", None)` when the tree
    is gone but its branch is not, `("setup", None)` for a review of a PR
    with no checkout of its own (`review_needs_checkout`), else
    `(None, {"reason", "fix"})`: why Orc
    can't, and what the user does about it (`fix.command` when that is a
    command to run)."""
    wt = meta.get("worktree") if isinstance(meta.get("worktree"), dict) else {}
    adapter, path = wt.get("adapter"), wt.get("path")
    project = meta.get("mainRepoPath") if isinstance(meta.get("mainRepoPath"), str) else None
    devd = bool(project) and devd_launch.is_devd_repo(project)
    if unadopted_qa_checkout(meta) is not None:
        if project and not devd and _repo_worktree_server(meta) is None:
            return None, _qa_missing_server(project)
        return "start", None
    if review_needs_checkout(meta) is not None:
        return "setup", None
    if wt.get("enabled") and isinstance(path, str) and os.path.isdir(path):
        if adapter == "devd":
            return "start", None
        if adapter == "generic":
            return ("start", None) if _repo_worktree_server(meta) is not None else (None, _qa_missing_server(project))
        if adapter == "rails":
            return None, {"reason": "This run's worktree still uses the retired rails adapter, "
                                    "which Orc no longer starts.",
                          "fix": {"text": "Move it to orc-devd, then press Start.",
                                  "command": "orc-worktree adopt-legacy-rails"}}
        return None, {"reason": "Orc does not know how to start this run's worktree "
                                "(adapter: %s)." % (adapter or "none"),
                      "fix": {"text": "Start the app yourself in %s." % path}}
    branch = meta.get("branch")
    if not isinstance(branch, str) or not branch.strip():
        return None, {"reason": "This run has no branch of its own, so it has no app to start.",
                      "fix": {"text": "Follow the steps on main's app instead."}}
    if not project or not os.path.isdir(project):
        return None, {"reason": "The project folder %s is not on this computer." % (project or "(unknown)"),
                      "fix": {"text": "Clone the project back to that folder, then press Recreate."}}
    if not _local_branch_exists(project, branch):
        return None, {"reason": "The worktree is gone and its branch %s is not on this computer "
                                "any more, so there is nothing to recreate it from." % branch,
                      "fix": {"text": "Fetch the branch back, then press Recreate.",
                              "command": "git -C %s fetch origin %s:%s" % (
                                  shlex.quote(project), shlex.quote(branch), shlex.quote(branch))}}
    if not devd and _repo_worktree_server(meta) is None:
        return None, _qa_missing_server(project)
    return "recreate", None


def _devd_problems(wt):
    """The run's orc-devd processes that stopped on an error, as
    [{process, detail, log}], so a dead `hmr` shows up beside the app."""
    devd_id = _devd_id(wt)
    with DEVD_STATUS_LOCK:
        row = DEVD_STATUS.get(devd_id) if devd_id else None
    return list(row.get("problems") or []) if row else []


def _qa_problems(run_id, wt):
    """The run's stopped processes, each with the fix for what its log says
    when one matches (`fix`, else None): the enabled plugins' fixes first,
    then Orc's own. A project on the plain dev server setting has one: the
    install or dev server whose last start failed."""
    problems = _devd_problems(wt)
    operation = wt.get("operation") if isinstance(wt.get("operation"), dict) else {}
    if not problems and operation.get("state") == "failed" and wt.get("slug"):
        stopped = worktree_servers.read_problem(os.path.join(RUNS, run_id), wt)
        problems = [stopped] if stopped else []
    fixes = APP_PLUGINS.qa_setup_fixes() + qa_setup_fix.BUILTIN_FIXES if problems else []
    return [dict(problem, fix=qa_setup_fix.match_fix(problem.get("lines"), fixes)) for problem in problems]


def _qa_app_state(run_id, meta):
    """The run's own app as the QA window shows it. A stopped app carries
    what Start does (`startAction`: start or recreate); one Orc can't start
    carries `blocked`: the plain reason and the fix."""
    wt = meta.get("worktree") if isinstance(meta.get("worktree"), dict) else {}
    start_action, blocked = _qa_app_plan(meta)
    can_start = start_action is not None
    operation = wt.get("operation") if isinstance(wt.get("operation"), dict) else {}
    url = worktree_app_root_url(meta)
    with WORKTREE_APP_HEALTH_LOCK:
        health = WORKTREE_APP_HEALTH.get(run_id)
    state, error = "none", None
    if operation.get("state") in ("requested", "running") and operation.get("action") in QA_APP_STARTS:
        state = "starting"
    elif url and worktree_app_running(run_id, meta):
        state = "running"
    elif url and health == "error":
        state, error = "error", "The app answers with a server error."
    elif operation.get("state") == "failed" and operation.get("action") in QA_APP_STARTS \
            and not (blocked or {}).get("fix", {}).get("setupProject"):
        state, error = "error", operation.get("error") or "The app could not be started."
    elif can_start:
        state = "stopped"
    return {"label": "This PR" if qa_pull_request(meta) else "This run", "state": state,
            "url": url if state == "running" else None, "canStart": can_start, "error": error,
            "startAction": start_action if can_start else None,
            "blocked": blocked if state == "none" else None,
            "problems": _qa_problems(run_id, wt), "setupFix": qa_setup_fix.view(run_id)}


QA_APP_STARTS = ("start", "restart", "recreate", "setup")


def _qa_main_state(meta):
    """The project's main app, which an MCP step compares the run against."""
    project = meta.get("mainRepoPath")
    if not isinstance(project, str) or not project:
        return {"label": "main", "state": "none", "url": None, "canStart": False, "error": None,
                "blocked": {"reason": "This run has no project, so it has no main app to compare against.",
                            "fix": {"text": "Follow the steps in your own browser."}}}
    if devd_launch.is_devd_repo(project):
        # orc-devd keeps the main checkout's app up and answers for it.
        return {"label": "main", "state": "running", "url": None, "canStart": False, "error": None}
    key = canonical_path(project)
    configured = _repo_worktree_server({"mainRepoPath": key}) is not None
    with MAIN_SERVER_OPS_LOCK:
        op = dict(MAIN_SERVER_OPS.get(key) or {})
    live = main_server_live(main_server_states().get(key))
    state, error = "none", None
    if op.get("state") == "running" and op.get("action") in ("start", "restart"):
        state = "starting"
    elif live and live.get("url"):
        state = "running"
    elif op.get("error"):
        state, error = "error", op["error"]
    elif configured:
        state = "stopped"
    return {"label": "main", "state": state, "url": live.get("url") if state == "running" else None,
            "canStart": configured, "error": error,
            "blocked": _qa_missing_server(project) if state == "none" else None}


def qa_command_env(run_id, meta):
    """A command step's environment: the server's own, plus where the two
    apps answer so a script can reach them."""
    return {**os.environ, **qa_command_urls(run_id, meta)}


def _qa_shell_preview():
    return IS_PREVIEW or bool(PREVIEW_ROOT) or DEMO.active


def _qa_shell_status(meta, terminal_allowed):
    if not terminal_allowed:
        return {"available": False, "reason": "QA runs on the computer Orc runs on."}
    if _qa_shell_preview():
        return {"available": True, "preview": "\x1b[36mqa-sandbox\x1b[0m $ "}
    cwd = run_checkout_dir(meta)
    if not cwd or not os.path.isdir(cwd):
        return {"available": False, "reason": "This run's checkout is not on this computer."}
    return qa_sandbox.availability()


def qa_app_action(run_id, meta, target, do):
    """Start or restart the run's app or the project's main app, through
    the same paths the run header and the Servers page use."""
    if target not in ("pr", "main") or do not in QA_APP_STARTS or (target == "main" and do in ("recreate", "setup")):
        raise qa_hub.ActionError(400, "unknown app action")
    if target == "main":
        status, body, _ = begin_main_server_action(meta.get("mainRepoPath"), do)
        if status >= 400:
            raise qa_hub.ActionError(status, body.get("error") or "The server action failed.")
        return
    start_action, blocked = _qa_app_plan(meta)
    if start_action is None:
        raise qa_hub.ActionError(409, blocked["reason"])
    if start_action == "setup":
        pr = review_needs_checkout(meta)
        operation = new_worktree_operation("setup")
        with RUN_STATUS_LOCK:
            fresh = run_meta(run_id)
            worktree = fresh.get("worktree") if isinstance(fresh.get("worktree"), dict) else {}
            worktree["operation"] = operation
            fresh["worktree"] = worktree
            _write_run_meta(run_id, fresh)
        threading.Thread(target=_set_up_review_checkout, args=(run_id, operation["token"], pr["url"]),
                         name="orc-qa-setup", daemon=True).start()
        return
    checkout = unadopted_qa_checkout(meta)
    if checkout:
        # Orc has not adopted the checkout: a QA run's first try failed
        # before the helper could say which adapter runs it, or a code
        # review of a PR runs in a review checkout. Adopting starts the app.
        with RUN_STATUS_LOCK:
            fresh = run_meta(run_id)
            worktree = fresh.get("worktree") if isinstance(fresh.get("worktree"), dict) else {}
            # Orc did not create the checkout, so it is never Orc's to delete.
            worktree.update(enabled=True, path=checkout, managedByOrc=False,
                            operation=new_worktree_operation("start"))
            fresh["worktree"] = worktree
            _write_run_meta(run_id, fresh)
        threading.Thread(target=_adopt_run_checkout, args=(run_id, checkout),
                         name="orc-qa-app", daemon=True).start()
        return
    request = operations.application_request(globals(), "POST", "/runs/%s/worktree-app" % run_id)
    request.worktree_app_action(run_id, {"action": "recreate" if start_action == "recreate" else do})
    result = request.result
    if result is None or result.status >= 400:
        raise qa_hub.ActionError(result.status if result else 500,
                                 ((result.data or {}).get("error") if result else None)
                                 or "The app could not be started.")


def _qa_after_setup_fix(run_id):
    """Starts the run's app again once a setup fix exited cleanly, the way
    the QA window's own button does. The error text when it can't."""
    meta = run_meta(run_id)
    start_action, blocked = _qa_app_plan(meta)
    if start_action is None:
        return (blocked or {}).get("reason") or "Orc can't start this app."
    try:
        qa_app_action(run_id, meta, "pr", "restart" if start_action == "start" else start_action)
    except qa_hub.ActionError as error:
        return error.message
    return None


def qa_setup_fix_action(run_id, meta, do, fix_id):
    """Run it, Open a terminal here or Close for the fix the QA window
    offers. Run only starts the command of the fix the current log still
    matches, never text the page sent, so the page can only ask for a fix Orc
    itself offered. The terminal is a login shell in the run's checkout,
    outside the QA sandbox, for what no fix knows; it starts nothing after."""
    if do == "close":
        qa_setup_fix.close(run_id)
        return
    running = qa_setup_fix.get(run_id)
    if do == "terminal":
        if running and running.exit_code is None:
            raise qa_hub.ActionError(409, "A terminal or fix is already open.")
        qa_setup_fix.start(run_id, qa_setup_fix.TERMINAL,
                           run_checkout_dir(meta) or os.path.expanduser("~"), lambda: None)
        return
    if do != "run" or not isinstance(fix_id, str):
        raise qa_hub.ActionError(400, "unknown setup fix action")
    wt = meta.get("worktree") if isinstance(meta.get("worktree"), dict) else {}
    fix = next((problem["fix"] for problem in _qa_problems(run_id, wt)
                if problem.get("fix") and problem["fix"]["id"] == fix_id), None)
    if fix is None:
        raise qa_hub.ActionError(409, "That fix no longer matches why setup stopped. Start the app again.")
    if running and running.exit_code is None:
        raise qa_hub.ActionError(409, "The fix is still running.")
    qa_setup_fix.start(run_id, fix, run_checkout_dir(meta) or os.path.expanduser("~"),
                       lambda: _qa_after_setup_fix(run_id))


def qa_review_draft_run(run_id, meta):
    """The run whose drafted review a QA window's failures go into, as
    (run id, run dir, meta): a code review run itself, or the review child of
    a QA run from before Review in Orc ran the review alone. None when there
    is no such run."""
    if reviewed_pull_request(meta):
        return run_id, os.path.join(RUNS, run_id), meta
    if not is_qa_run(meta):
        return None
    try:
        with open(os.path.join(RUNS, run_id, QA_REVIEW), encoding="utf-8") as handle:
            record = json.load(handle)
    except (OSError, ValueError):
        return None
    child_id = record.get("runId") if isinstance(record, dict) else None
    if not isinstance(child_id, str) or not _existing_run_id(child_id):
        return None
    return child_id, os.path.join(RUNS, child_id), run_meta(child_id)


def qa_run_head(meta):
    checkout = run_checkout_dir(meta)
    return _git_value(checkout, "rev-parse", "HEAD", timeout=10) if checkout and os.path.isdir(checkout) else None


def qa_failure_delivery(run_id, meta):
    """Where the QA window sends failed steps (ui/qa_hub.py): your review of
    a pull request, else the run's own agent, whose Chat must still take a
    message. The target is decided here, never by the window, so a
    colleague's step text only ever reaches your draft."""
    if qa_pull_request(meta):
        found = qa_review_draft_run(run_id, meta)
        state = pr_review_draft.qa_status(found[1], found[2]) if found else "none"
        return {"target": "review", "state": state}
    return {"target": "agent", "state": "open" if meta.get("status") in CHAT_QUEUE_STATUSES else "finished",
            "head": lambda: qa_run_head(meta)}


def send_qa_failures(run_id, meta, document, shown):
    """The QA window's Add to your review / Send to the agent."""
    run_dir = os.path.join(RUNS, run_id)
    delivery = qa_failure_delivery(run_id, meta)
    if delivery["state"] == "posted":
        raise qa_hub.ActionError(409, "Your review is already on GitHub, so it takes no more comments.")
    if delivery["state"] != "open":
        raise qa_hub.ActionError(409, "Your review has no draft yet." if delivery["target"] == "review"
                                 else "This run has finished, so its agent takes no messages.")
    if delivery["target"] == "review":
        _draft_id, draft_dir, draft_meta = qa_review_draft_run(run_id, meta)

        def deliver(failures):
            comments = [qa_hub.review_comment(item, qa_hub.stage_shots(item["shots"], draft_dir))
                        for item in failures]
            try:
                pr_review_draft.add_comments(draft_dir, draft_meta, comments)
            except pr_review_draft.DraftError as error:
                raise qa_hub.ActionError(error.status, qa_hub.sentence(str(error))) from None
        return qa_hub.send_failures(run_dir, run_id, document, shown, "review", deliver)

    def deliver(failures):
        root = os.path.realpath(run_dir)
        attachments = {item["id"]: [os.path.join(root, path) for path in qa_hub.stage_shots(item["shots"], run_dir)]
                       for item in failures}
        _state, error = queue_follow_up(run_id, qa_hub.agent_message(failures, attachments), source="chat")
        if error:
            raise qa_hub.ActionError(error[0], qa_hub.sentence(error[1]))
        if flush_follow_ups(run_id):
            unsettle_messaged_run(run_id)
    return qa_hub.send_failures(run_dir, run_id, document, shown, "agent", deliver, commit=qa_run_head(meta))


def launch_ticket(data, ticket):
    agent = data.get("agent")
    mode = data.get("mode")
    if agent not in NEW_CONV_AGENTS:
        return None, (400, harnesses.refusal(agent))
    if mode not in NEW_CONV_MODES:
        return None, (400, "unknown mode")
    permission = data.get("permissionMode") or launch_permission_default(agent)
    if not isinstance(permission, str) \
            or permission not in NEW_CONV_PERMISSION_MODES.get(agent, {}):
        return None, (400, "unknown permission mode")
    try:
        model_effort_args = launch_model_effort_args(agent, data, mode)
    except ValueError as exc:
        return None, (400, str(exc))
    account_kwargs, account_error = launch_account_kwargs(agent, data)
    if account_error:
        return None, (400, account_error)
    permission_args = list(NEW_CONV_PERMISSION_MODES[agent][permission]) + model_effort_args
    transport = data.get("transport") or default_transport()
    spawn = new_conv_spawn_for(transport)
    if spawn is None:
        return None, (400, "unknown transport")
    # A ticket names no project, so the caller says where it runs.
    cwd = configured_repo_cwd(data.get("project"))
    if not cwd:
        return None, (400, "project is not a configured project")
    unavailable = transport_unavailable(transport)
    if unavailable:
        return None, (409, unavailable)
    if shutil.which(headless_session.agent_binary(agent)) is None:
        return None, (409, agent + " not found on PATH")
    # The ticket *is* the prompt — its body, exactly as written, so what
    # runs is what you can read on the page. The identifier is deliberately
    # not part of it: a run called ORC-1 says nothing.
    prompt = ticket_image_references((ticket.get("body") or "").strip(), [ticket])
    if not prompt:
        return None, (409, "this ticket has nothing written in it yet")
    with launch_usage_source("ticket"):
        return spawn(cwd, agent, mode, prompt, permission_args, **account_kwargs)


