class ApplicationHandler:
    def do_GET(self):
        public_pwa = {
            "/manifest.webmanifest": "application/manifest+json",
            "/sw.js": "text/javascript", "/pwa.js": "text/javascript",
            "/pwa.css": "text/css", "/offline.html": "text/html",
            "/ticket-outbox.js": "text/javascript",
            "/offline-ticket-page.js": "text/javascript",
            "/vendor/orc-ds.tokens.css": "text/css",
            "/vendor/orc-ds.min.js": "text/javascript",
            **{"/pwa/" + name: "image/png" for name in (
                "icon-180.png", "icon-192.png", "icon-512.png", "icon-maskable-512.png")},
        }
        pwa_path = self.path.split("?", 1)[0]
        if pwa_path in public_pwa and not self._phone_takes_laptops_code(pwa_path):
            try:
                with open(os.path.join(HERE, pwa_path.lstrip("/")), "rb") as f:
                    body = f.read()
            except OSError:
                return self.send_error(404)
            ctype = public_pwa[pwa_path]
            headers = FRAME_DENY_HEADERS if ctype == "text/html" else None
            return self._respond(200, body, ctype, headers)
        if not self._lan_gate():
            return
        path = unquote(self.path.split("?", 1)[0])
        if self.demo_fixture("GET", path):
            return
        if dispatch_host_service(self, "GET", path):
            return
        if re.fullmatch(r"/qa/[A-Za-z0-9][A-Za-z0-9_.-]*", path):
            # The QA window: its own page, so Orc.app can give it its own window.
            try:
                with open(os.path.join(HERE, "qa.html"), "rb") as f:
                    body = f.read()
            except OSError:
                return self.send_error(404)
            # Its Run button starts a command, so no other page may frame it.
            return self._respond(200, self._with_host_state(body), "text/html",
                                 FRAME_DENY_HEADERS)
        if path == "/":
            try:
                with open(os.path.join(HERE, "index.html"), "rb") as f:
                    body = f.read()
            except OSError:
                return self.send_error(404)
            body = self._with_host_state(body)
            plugins = self._initial_app_plugins()
            if not offers_fast_mode():
                body = body.replace(b"window.ORC_OFFER_FAST_MODE = true;", b"window.ORC_OFFER_FAST_MODE = false;")
            no_fast = claude_accounts.fast_unavailable()
            if no_fast:
                body = body.replace(b"window.ORC_CLAUDE_FAST_UNAVAILABLE = [];",
                                    b"window.ORC_CLAUDE_FAST_UNAVAILABLE = " + json.dumps(no_fast).encode() + b";")
            if not shows_usage():
                body = body.replace(b"window.ORC_SHOW_USAGE = true;", b"window.ORC_SHOW_USAGE = false;")
            if pr_push_action() != project_settings.DEFAULT_PR_PUSH_ACTION:
                body = body.replace(b'window.ORC_PR_PUSH_ACTION = "comments-and-commits";',
                                    b'window.ORC_PR_PUSH_ACTION = "commits";')
            if not offer_ship_when_done():
                body = body.replace(b"window.ORC_OFFER_SHIP_WHEN_DONE = true;",
                                    b"window.ORC_OFFER_SHIP_WHEN_DONE = false;")
            if host_animations_off():
                body = body.replace(b"window.ORC_HOST_ANIMATIONS_OFF = false;", b"window.ORC_HOST_ANIMATIONS_OFF = true;")
            if (self._secret_entry_local() and not DEMO.active
                    and APP_PLUGINS.allows_feature("animations-gallery")):
                body = body.replace(b"window.ORC_SHOW_ANIMATIONS_GALLERY = false;",
                                    b"window.ORC_SHOW_ANIMATIONS_GALLERY = true;")
            if offers_permission_switch():
                body = body.replace(b"window.ORC_OFFER_PERMISSIONS = false;", b"window.ORC_OFFER_PERMISSIONS = true;")
            if configured_permission_default() == "bypass":
                body = body.replace(b'window.ORC_PERMISSION_DEFAULT = "auto";', b'window.ORC_PERMISSION_DEFAULT = "bypass";')
            body = body.replace(b"window.ORC_APP_PLUGINS = null;",
                                b"window.ORC_APP_PLUGINS = " + json.dumps(plugins).replace('<', '\\u003c').encode() + b";")
            body = body.replace(b"window.ORC_BUILTIN_HARNESSES = null;", builtin_harnesses_js().encode())
            styles = ''.join('<link rel="stylesheet" data-app-plugin-style="%s" href="%s">' %
                             (row['id'], row['base'] + row['contributes']['theme']['css'])
                             for row in plugins['plugins'] if row['enabled'] and not row['error'] and row.get('contributes', {}).get('theme'))
            body = body.replace(b'<!-- app-plugin-styles -->', styles.encode())
            # Same thumbnail tray the gate pages get, pointed at the runless
            # store and scoped to the New conversation prompt.
            body = body.replace(b"</body>", COMPOSER_ATTACHMENTS_JS + b"</body>", 1)
            return self._respond(200, body, "text/html", FRAME_DENY_HEADERS)
        if path == "/api/sidebar-settled":
            try:
                return self.send_body(json.dumps(read_sidebar_settled()).encode(), "application/json")
            except (ValueError, OSError, TypeError):
                return self.json_error(500, "could not read settled runs")
        if path == "/api/github-emoji":
            return self.send_body(json.dumps(github_emoji.table(GITHUB_EMOJI_PATH)).encode(), "application/json")
        if path == "/api/priority-runs":
            return self.send_body(json.dumps({"runs": power_mode.read_priority(CONFIG_DIR)}).encode(), "application/json")
        if path == "/api/lan":
            return self.send_body(json.dumps(self.lan_status()).encode(), "application/json")
        if path == "/api/link" or path.startswith("/api/link/"):
            return self.link_request(path[len("/api/link"):].lstrip("/"))
        checkout_match = re.fullmatch(r"/runs/([A-Za-z0-9][A-Za-z0-9_.-]*)/checkout/(.+)", path)
        if checkout_match:
            return self.serve_checkout_page(checkout_match[1], checkout_match[2])
        if path.startswith("/api/attachments/"):
            return ATTACHMENTS_SERVICE.get_staged(self, path)
        if path == '/api/app-plugins':
            return self.get_app_plugins()
        if path == '/app-plugin-themes.css':
            return self._respond(200, APP_PLUGINS.theme_css().encode(), 'text/css', {'Cache-Control': 'no-store'})
        if path == '/app-plugin-state.js':
            body = ('window.ORC_APP_PLUGINS = ' + json.dumps(self._initial_app_plugins()).replace('<', '\\u003c') + ';\n'
                    + builtin_harnesses_js())
            return self._respond(200, body.encode(), 'text/javascript', {'Cache-Control': 'no-store'})
        if path.startswith('/app-plugin-assets/'):
            try:
                return self.send_viewer_asset(str(APP_PLUGINS.asset(path[len('/app-plugin-assets/'):])) )
            except app_plugins.PluginError:
                return self.send_error(404)
        if APP_PLUGIN_RUNTIME.dispatch(self, 'GET', path):
            return
        if path in (
            "/activity.css", "/animations-gallery.css", "/answer-mode.css", "/app-plugins.css", "/chat.css",
            "/command-palette.css", "/control.css", "/dev-servers.css", "/diff-panel.css", "/factory.css",
            "/landing-actions.js", "/laptop-cover.js", "/markdown-editor.css", "/marked.min.js", "/mcp-tab.css",
            "/md-callouts.css", "/md-callouts.js", "/md-copy.js", "/mobile-shell.css", "/now-playing.css",
            "/orc-aliases.css", "/orchestrate.css", "/plan-page.css", "/project-home.css", "/provider-usage.css",
            "/qa-window.css", "/ready-fanfare.wav", "/run-content.css", "/run-header.css", "/run-sidebar.css",
            "/run-terminal.css", "/screen-transitions.css", "/settings.css", "/shell-base.css", "/shell-dialogs.css",
            "/sidebar-footer.css", "/table-resize.js", "/theme-preview.css", "/waterfall.css", "/yeet-preview.html",
        ):
            return self.send_viewer_asset(os.path.join(HERE, path.lstrip("/")))
        if path.startswith("/sounds/"):
            # The clips Settings' Sounds tab offers (ui/sounds/), basenames only.
            name = path[len("/sounds/"):]
            if not re.fullmatch(r"[a-z-]+\.mp3", name):
                return self.send_error(404)
            clip = os.path.join(HERE, "sounds", name)
            if self.headers.get("Range"):
                return self.send_file(clip)
            return self.send_viewer_asset(clip)
        if path.startswith("/api/sounds/"):
            # A sound someone added in Settings → Sounds (~/.orc/sounds/).
            name = path[len("/api/sounds/"):]
            full = custom_sounds.path_for(CONFIG_DIR, name)
            if not full:
                return self.send_error(404)
            try:
                with open(full, "rb") as handle:
                    body = handle.read()
            except OSError:
                return self.send_error(404)
            return self._respond(200, body, custom_sounds.CONTENT_TYPES[name.rsplit(".", 1)[1]],
                                 {"Cache-Control": "no-cache"})
        if path.startswith("/gallery-backdrops/"):
            # The pages a gallery MP4 plays its send-off over
            # (ui/gallery-backdrops/), basenames only.
            name = path[len("/gallery-backdrops/"):]
            if not re.fullmatch(r"[a-z-]+\.(jpg|json)", name):
                return self.send_error(404)
            full = os.path.join(HERE, "gallery-backdrops", name)
            if not os.path.isfile(full):
                return self.send_error(404)
            return self.send_viewer_asset(full)
        if path.startswith("/vendor/"):
            name = os.path.basename(path)
            if not name.endswith((".js", ".mjs", ".css")) or name != path[len("/vendor/"):]:
                return self.send_error(404)
            full = os.path.join(HERE, "vendor", name)
            if not os.path.isfile(full):
                return self.send_error(404)
            return self.send_viewer_asset(full)
        if path.startswith("/theme-kit/"):
            # The scene kit themes import by URL (app-plugins/build.mjs,
            # app-plugins/theme-surface.json). Every API version this Orc
            # still loads is served from the one current build.
            kit = re.fullmatch(r"/theme-kit/([1-9][0-9]{0,3})/([\w-]+\.js)", path)
            if not kit or int(kit[1]) > app_plugins.API_VERSION:
                return self.send_error(404)
            full = os.path.join(HERE, "vendor", "theme-kit", kit[2])
            if not os.path.isfile(full):
                return self.send_error(404)
            return self.send_viewer_asset(full)
        if path.startswith("/js/"):
            # The viewer's own ES modules (ui/js/*.js). Same shape as /vendor/
            # above: plain .js basenames only, no path traversal.
            name = os.path.basename(path)
            if not name.endswith(".js") or name != path[len("/js/"):]:
                return self.send_error(404)
            full = os.path.join(HERE, "js", name)
            if not os.path.isfile(full):
                return self.send_error(404)
            return self.send_viewer_asset(full)
        if path.startswith("/assets/model-icons/"):
            name = path[len("/assets/model-icons/"):]
            if name not in {"sun.png", "star.png", "moon.png", "opus.png", "sonnet.png", "fable.png", "book.png"}:
                return self.send_error(404)
            full = os.path.join(HERE, "assets", "model-icons", name)
            if not os.path.isfile(full):
                return self.send_error(404)
            return self.send_file(full)
        if path in ("/assets/persona/gary.png", "/assets/persona/sheila.png"):
            # The assistant's face for a theme that ships no cutouts of its own.
            full = os.path.join(os.path.dirname(HERE), "assets", "persona", os.path.basename(path))
            if not os.path.isfile(full):
                return self.send_error(404)
            return self.send_file(full)
        if path.startswith("/fonts/"):
            name = os.path.basename(path)
            if not name.endswith(".woff2"):
                return self.send_error(404)
            full = os.path.join(HERE, "fonts", name)
            try:
                with open(full, "rb") as f:
                    body = f.read()
            except OSError:
                return self.send_error(404)
            self.send_response(200)
            self.send_header("Content-Type", "font/woff2")
            self.send_header("Access-Control-Allow-Origin", "null")
            self.send_header("Content-Length", str(len(body)))
            # vendored files change name when they change content
            self.send_header("Cache-Control", "public, max-age=31536000, immutable")
            self.end_headers()
            return self.wfile.write(body)
        if path == "/api/runs":
            # The viewer names its part in a header: Playwright route globs
            # such as **/api/runs never match a query string.
            part = (parse_qs(urlsplit(self.path).query).get("part", [None])[0]
                    or self.headers.get("X-Orc-Runs-Part"))
            if part in RUNS_PARTS:
                entry = runs_body_entry(part)
                body, etag = entry["body"], entry["etag"]
            else:
                result = operations.runs_list(globals(), raw=True)
                body, etag, entry = result.data, result.headers["ETag"], {}
            config = read_config()[0]
            headers = {"ETag": etag, "X-Orc-Build": UI_BUILD,
                       "Vary": "X-Orc-Runs-Part, " + runs_delta.DELTA_BASE_HEADER,
                       "X-Orc-Power-Mode": power_mode.mode(config),
                       "X-Orc-Queue-Builds-Only": str(power_mode.builds_only(config)).lower(),
                       "X-Orc-Priority-Runs": json.dumps(power_mode.read_priority(CONFIG_DIR))}
            if "settledEtag" in entry:
                headers["X-Orc-Settled-Etag"] = entry["settledEtag"]
            # The viewer polls this every 3s and most polls change nothing.
            # A 304 costs the browser no transfer, no 6.5MB parse and no
            # re-render, which is the difference between a smooth UI and a
            # ~400ms main-thread stall every tick.
            if self.headers.get("If-None-Match") == etag:
                return self._respond(304, b"", "application/json", headers)
            if part in RUNS_PARTS:
                delta_base = self.headers.get(runs_delta.DELTA_BASE_HEADER)
                if delta_base:
                    delta_body = RUNS_DELTA_HISTORY[part].delta_for(
                        delta_base, etag, full_len=len(body))
                    if delta_body is not None:
                        body = delta_body
                        headers[runs_delta.DELTA_RESPONSE_HEADER] = "1"
            return self._respond(200, body, "application/json", headers)
        if re.fullmatch(r"/api/runs/[^/]+", path):
            result = operations.OperationService(globals()).call(
                "runs.get", {"runId": path.rsplit("/", 1)[1]}, ["orc:read"])
            return self._respond(result.status, json.dumps(result.data).encode(), result.content_type)
        if dispatch_domain(self, "GET", path):
            return
        if path == "/api/repo-status":
            # Only configured projects: every one costs git subprocesses and
            # may start a background fetch.
            query = parse_qs(self.path.split("?", 1)[1] if "?" in self.path else "")
            commits = (query.get("commits") or [""])[0] == "1"
            projects = []
            for project in dict.fromkeys(query.get("project") or []):
                cwd = configured_repo_cwd(project)
                if not cwd:
                    continue
                status = repo_sync_status(cwd, commits=commits)
                if status["branch"] and status["state"] != "no-remote":
                    refresh_repo_sync(cwd, status["branch"])
                projects.append(dict(status, project=project))
            return self.send_body(json.dumps({"projects": projects}).encode(),
                                  "application/json")
        if path == "/api/project-verification":
            query = parse_qs(self.path.split("?", 1)[1] if "?" in self.path else "")
            result = project_verification_status((query.get("project") or [""])[0])
            if result is None:
                return self.json_error(404, "project not found", False)
            return self.send_body(json.dumps(result).encode(), "application/json")
        if path == "/api/project-icon":
            # Configured projects only, the same trust boundary as repo-status:
            # this reads files, so an arbitrary path must never reach it.
            query = parse_qs(self.path.split("?", 1)[1] if "?" in self.path else "")
            cwd = configured_repo_cwd((query.get("project") or [""])[0])
            full = resolve_project_icon(cwd) if cwd else None
            try:
                with open(full, "rb") as f:
                    body = f.read(MAX_ATTACHMENT_BYTES + 1)
            except (OSError, TypeError):
                return self.send_error(404)
            if len(body) > MAX_ATTACHMENT_BYTES:
                return self.json_error(413, "project icon exceeds 10 MB")
            etag = '"%s"' % hashlib.sha256(full.encode() + body).hexdigest()[:16]
            if self.headers.get("If-None-Match") == etag:
                return self._respond(304, extra_headers={"ETag": etag})
            return self._respond(200, body, PROJECT_ICON_TYPES[os.path.splitext(full)[1].lower()], {
                "ETag": etag,
                # An SVG is a document; it only ever loads through <img>, but
                # opened directly it must not run script either.
                "Content-Security-Policy": "default-src 'none'; style-src 'unsafe-inline'",
                "X-Content-Type-Options": "nosniff",
            })
